/** Version-aware injected storage keeps real transactional tests away from application buckets. */
class Storage implements AdminVideoStorage {
    objects = new Map<string, { bytes: Buffer; asset: AdminVideoObject; identity: AdminVideoStorageIdentity }>();
    puts = 0; copies = 0; deletes = 0; losePut = false; loseCopy = false; failDelete = false;
    async put(_projectId: string, asset: AdminVideoObject, file: Express.Multer.File) {
        this.puts++;
        assert.ok(!this.objects.has(asset.key));
        const bytes = file.path ? await readFile(file.path) : file.buffer;
        assert.equal(bytes.length, asset.byteLength);
        assert.equal(createHash('sha256').update(bytes).digest('hex'), asset.sha256);
        const identity = { etag: `"${asset.id}"`, versionId: `version-${asset.id}` };
        this.objects.set(asset.key, { bytes, asset: { ...asset }, identity });
        if (this.losePut) { this.losePut = false; throw new Error('Synthetic lost acknowledgement'); }
        return identity;
    }
    async head(_projectId: string, asset: AdminVideoObject) {
        const value = this.objects.get(asset.key);
        if (!value) return null;
        assert.equal(value.asset.sha256, asset.sha256); assert.equal(value.asset.byteLength, asset.byteLength);
        if (asset.etag !== null) assert.deepEqual(value.identity, { etag: asset.etag, versionId: asset.versionId });
        return value.identity;
    }
    async download(_projectId: string, asset: AdminVideoObject, path: string) {
        const value = this.objects.get(asset.key); assert.ok(value); await writeFile(path, value.bytes, { flag: 'wx' });
    }
    async copy(projectId: string, source: AdminVideoObject, target: AdminVideoObject) {
        this.copies++; const value = this.objects.get(source.key); assert.ok(value);
        const result = await this.put(projectId, target, { buffer: value.bytes, size: value.bytes.length } as Express.Multer.File);
        if (this.loseCopy) { this.loseCopy = false; throw new Error('Synthetic lost copy acknowledgement'); }
        return result;
    }
    async delete(_projectId: string, asset: AdminVideoObject) {
        if (this.failDelete) throw new Error('Synthetic delete failure');
        const current = this.objects.get(asset.key); if (current) assert.deepEqual(current.identity, { etag: asset.etag, versionId: asset.versionId });
        this.deletes++; this.objects.delete(asset.key);
    }
    async readCover(_projectId: string, asset: AdminVideoObject) { const value = this.objects.get(asset.key); assert.ok(value); return value.bytes; }
}
let harness: MongoReplicaSetHarness;
let storage: Storage;
const actor = new ObjectId(), second = new ObjectId(), ordinary = new ObjectId();
const db = () => getDb()!;
const bytes = Buffer.from('synthetic-video-source-content');
const file = (name = 'travel.mp4'): Express.Multer.File => ({ originalname: name, size: bytes.length, buffer: bytes, mimetype: /mov$/i.test(name) ? 'video/quicktime' : 'video/mp4', fieldname: 'file', encoding: '7bit' } as Express.Multer.File);
const intent = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const errorCode = (code: string) => (error: any) => error.code === `ADMIN_VIDEO_${code}`;
const processor: NonNullable<AdminVideoWorkerDependencies['process']> = async ({ inputPath }) => ({
    outputPath: inputPath, contentType: 'video/mp4', byteLength: (await readFile(inputPath)).length,
    plan: 'direct', durationSeconds: 22.016, width: 3840, height: 2160, videoCodec: 'hevc', audioCodec: 'aac'
});
const step = (extra: AdminVideoWorkerDependencies = {}) => runAdminVideoWorkerOnce({ storage, process: processor, ...extra });
async function create(name = 'travel.mp4', owner = actor.toHexString()) {
    return createAdminVideoProject(owner, { operationId: randomUUID(), filename: name, byteLength: bytes.length });
}
async function uploaded(name = 'travel.mp4', owner = actor.toHexString()) {
    const created = await create(name, owner), operationId = randomUUID();
    const result = await uploadAdminVideoSource(owner, created.item.id, operationId, created.item.revision, file(name), storage);
    return { ...result, sourceOperationId: operationId };
}
async function reviewed() { const result = await uploaded(); await step(); return getAdminVideoProject(actor.toHexString(), result.item.id); }
async function approve(id: string) {
    const current = await getAdminVideoProject(actor.toHexString(), id);
    return publishAdminVideoProject(actor.toHexString(), id, { ...intent(current.item.revision), approvalDigest: current.item.approvalDigest });
}

