    process.env.CATALOG_CREDIT_WRITES_ENABLED = 'true';
    await retryAdminVideoPublication(actor.toHexString(), current.item.id, { operationId: approved.item.publication.operationId }); await step();
    assert.equal(storage.copies, 1); assert.equal(await db().collection('audioTracks').countDocuments(), 1);
