test('revoked oldest job cannot starve another current administrator', async () => {
    const first = await uploaded(), next = await uploaded('second.mp4', second.toHexString());
    await db().collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    await step(); await step();
    const failed = await videoProjects().findOne({ _id: new ObjectId(first.item.id) });
    assert.equal(failed?.processing.issue, 'permission_lost');
    assert.equal((await getAdminVideoProject(second.toHexString(), next.item.id)).item.processing.state, 'ready');
});

test('progress checkpoint permission loss aborts the processor without unhandled rejection or output writes', async () => {
    const current = await uploaded(); let aborted = false;
    await step({ process: async ({ signal, onProgress }) => {
        await db().collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
        onProgress?.({ stage: 'validate', progress: 100 });
        await new Promise<never>((_resolve, reject) => {
            const stop = () => { aborted = true; reject(new Error('Synthetic processor stopped')); };
            if (signal?.aborted) stop(); else signal?.addEventListener('abort', stop, { once: true });
        });
        throw new Error('Unreachable processor completion');
    } });
    assert.equal(aborted, true); assert.equal(storage.puts, 1);
    await step();
    const doc = await videoProjects().findOne({ _id: new ObjectId(current.item.id) });
    assert.equal(doc?.processing.issue, 'permission_lost'); assert.equal(doc?.assets.length, 1);
});

test('a worker that lost its lease cannot checkpoint or publish a late processing result', async () => {
    const current = await uploaded(), nextWorker = randomUUID();
    await step({ process: async input => {
        await videoProjects().updateOne({ _id: new ObjectId(current.item.id) }, { $set: { leaseOwner: nextWorker, leaseUntil: new Date(Date.now() + 60_000) } });
        return processor(input);
    } });
    const doc = await videoProjects().findOne({ _id: new ObjectId(current.item.id) });
    assert.equal(doc?.leaseOwner, nextWorker); assert.equal(doc?.outputId, null);
    assert.equal(doc?.assets.length, 1); assert.equal(await db().collection('audioTracks').countDocuments(), 0);
});

test('automatic cover stays available after custom choice, and a late selected frame cannot overwrite a newer cover choice', async () => {
    const current = await uploaded(); const image = await sharp({ create: { width: 12, height: 8, channels: 3, background: '#887766' } }).jpeg().toBuffer();
    await editAdminVideoProject(actor.toHexString(), current.item.id, { ...intent(current.item.revision), patch: { coverChoice: 'none' } });
    await step({ process: async input => { const result = await processor(input), path = join(input.workDirectory, 'cover.jpg'); await writeFile(path, image); return { ...result, cover: { path, contentType: 'image/jpeg', source: 'embedded' } }; } });
    let ready = await getAdminVideoProject(actor.toHexString(), current.item.id);
    assert.equal(ready.item.selectedCoverId, null); assert.equal(ready.item.covers.length, 1);
    ready = await editAdminVideoProject(actor.toHexString(), current.item.id, { ...intent(ready.item.revision), patch: { coverChoice: 'automatic' } });
    assert.equal(ready.item.selectedCoverId, ready.item.covers[0].id);
    await requestAdminVideoFrame(actor.toHexString(), current.item.id, { ...intent(ready.item.revision), timeSeconds: 2 });
    await step({ frame: async input => {
        const latest = await getAdminVideoProject(actor.toHexString(), current.item.id);
        await editAdminVideoProject(actor.toHexString(), current.item.id, { ...intent(latest.item.revision), patch: { coverChoice: 'none' } });
        const path = join(input.workDirectory, 'frame.jpg'); await writeFile(path, image); return { path, contentType: 'image/jpeg' };
    } });
    const complete = await getAdminVideoProject(actor.toHexString(), current.item.id);
    assert.equal(complete.item.frame.state, 'ready'); assert.equal(complete.item.draft.coverChoice, 'none'); assert.equal(complete.item.selectedCoverId, null); assert.equal(complete.item.covers.length, 2);
    await editAdminVideoProject(actor.toHexString(), current.item.id, { ...intent(complete.item.revision), patch: { coverChoice: 'automatic' } });
    await approve(current.item.id); await step(); await step();
    const published = await getAdminVideoProject(actor.toHexString(), current.item.id);
    assert.ok(published.item.covers.every(cover => cover.state === 'deleted'));
    assert.equal(published.item.publication.coverUrl, `/api/admin/v1/catalog/audioTrack/${published.item.publication.mediaTrackId}/artwork?viewer=${actor}`);
    assert.equal(await db().collection('imageAssets').countDocuments(), 1);
});

test('private projects block account deletion until explicit cancellation and confirmed cleanup', async () => {
    const current = await uploaded(); assert.deepEqual(await deleteListenerAccountData(actor.toHexString()), { status: 'sharedProvenance' });
    await cancelAdminVideoProject(actor.toHexString(), current.item.id, intent(current.item.revision)); storage.failDelete = true; await step();
    assert.deepEqual(await deleteListenerAccountData(actor.toHexString()), { status: 'sharedProvenance' });
    storage.failDelete = false; await step();
    assert.deepEqual(await deleteListenerAccountData(actor.toHexString()), { status: 'deleted' });
    assert.equal(await videoProjects().countDocuments(), 0); assert.equal(storage.objects.size, 0);
});

test('unknown absent writes retain evidence until their transfer deadline has settled', async () => {
    const current = await uploaded(); const doc = await videoProjects().findOne({ _id: new ObjectId(current.item.id) }); assert.ok(doc);
    const source = doc.assets.find(asset => asset.id === doc.sourceId)!; storage.objects.delete(source.key);
    await videoProjects().updateOne({ _id: doc._id }, { $set: { 'assets.0.state': 'unknown', 'assets.0.etag': null, 'assets.0.versionId': null } });
    const latest = await getAdminVideoProject(actor.toHexString(), current.item.id);
    await cancelAdminVideoProject(actor.toHexString(), current.item.id, intent(latest.item.revision)); await step();
    assert.equal((await videoProjects().findOne({ _id: doc._id }))?.cleanupComplete, false);
    await videoProjects().updateOne({ _id: doc._id }, { $set: { 'assets.0.settleAfter': new Date(0) } }); await step();
    assert.equal((await videoProjects().findOne({ _id: doc._id }))?.cleanupComplete, true);
});

test('default cover lost acknowledgement recovers its current automatic candidate without extracting again', async () => {
    const current = await uploaded(), image = await sharp({ create: { width: 12, height: 8, channels: 3, background: '#776655' } }).jpeg().toBuffer();
    await step({ process: async input => {
        const result = await processor(input), path = join(input.workDirectory, 'default.jpg');
        await writeFile(path, image); storage.losePut = true;
        return { ...result, cover: { path, contentType: 'image/jpeg', source: 'embedded' } };
    } });
    const ready = await getAdminVideoProject(actor.toHexString(), current.item.id), cover = ready.item.covers[0];
    assert.equal(ready.item.processing.state, 'ready'); assert.equal(cover.state, 'unknown'); assert.equal(ready.item.selectedCoverId, null);
    const before = storage.puts;
    const recovered = await reconcileVideoAsset(actor.toHexString(), current.item.id, cover.id, cover.operationId, storage);
    assert.equal(recovered.item.selectedCoverId, cover.id); assert.equal(recovered.receipt?.operationId, cover.operationId);
    assert.equal(storage.puts, before);
    await assert.rejects(requestAdminVideoFrame(actor.toHexString(), current.item.id, { operationId: cover.operationId, expectedRevision: recovered.item.revision, timeSeconds: 1 }), errorCode('OPERATION_CONFLICT'));
});

for (const changedChoice of [false, true]) test(`manual frame lost acknowledgement retains the requested selection intent (later choice=${changedChoice})`, async () => {
    const current = await reviewed(), image = await sharp({ create: { width: 12, height: 8, channels: 3, background: '#776655' } }).jpeg().toBuffer();
    const request = { ...intent(current.item.revision), timeSeconds: 1 };
    await requestAdminVideoFrame(actor.toHexString(), current.item.id, request);
    await step({ frame: async input => { const path = join(input.workDirectory, 'frame.jpg'); await writeFile(path, image); storage.losePut = true; return { path, contentType: 'image/jpeg' }; } });
    let failed = await getAdminVideoProject(actor.toHexString(), current.item.id);
    assert.equal(failed.item.frame.state, 'failed'); const cover = failed.item.covers[0]; assert.equal(cover.state, 'unknown');
    if (changedChoice) failed = await editAdminVideoProject(actor.toHexString(), current.item.id, { ...intent(failed.item.revision), patch: { coverChoice: 'none' } });
    const before = storage.puts;
    const recovered = await reconcileVideoAsset(actor.toHexString(), current.item.id, cover.id, request.operationId, storage);
    assert.equal(recovered.item.frame.state, 'ready');
    assert.equal(recovered.item.selectedCoverId, changedChoice ? null : cover.id);
    assert.equal(recovered.item.draft.coverChoice, changedChoice ? 'none' : cover.id);
    assert.equal(storage.puts, before);
});
